Subroutine Suspendable Cocinar(precio As Integer, porciones As Integer) As Integer
  Return precio * porciones;
EndSubroutine

Algorithm Bandeja
  Define jugos As Integer;
  Define sandwiches As Integer;
  Define frutas As Integer;
  Read jugos;
  Read sandwiches;
  Read frutas;
  Tasks
    Define deJugos As Task<Integer> <- Spawn Cocinar(3, jugos);
    Define deSandwiches As Task<Integer> <- Spawn Cocinar(5, sandwiches);
    Define deFrutas As Task<Integer> <- Spawn Cocinar(2, frutas);
    Write "Bandeja: ", Await deJugos + Await deSandwiches + Await deFrutas, " pesos";
  EndTasks
EndAlgorithm
